import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const scriptDir = path.dirname(fileURLToPath(import.meta.url))
const rootDir = path.resolve(scriptDir, '..')
const contractPath = path.join(rootDir, 'contracts', 'http-routes.json')

const frontendOut = path.join(
  rootDir,
  'web',
  'src',
  'api',
  'route-policy.constants.generated.ts',
)

const edgeOut = path.join(
  rootDir,
  'edge',
  'entry',
  'dispatch.constants.generated.ts',
)

const banner = `/**
 * AUTO-GENERATED BY scripts/generate-http-route-constants.mjs
 * Source: contracts/http-routes.json
 * Do not edit by hand — run: node scripts/generate-http-route-constants.mjs
 */
`

function tsQuote(s) {
  return `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
}

function formatArray(items) {
  return items.map(s => `  ${tsQuote(s)},`).join('\n')
}

function buildFrontendSource(edgeOnly, direct) {
  return `${banner}
export const EDGE_ONLY_RULES = [
${formatArray(edgeOnly)}
] as const

export const DIRECT_RULES = [
${formatArray(direct)}
] as const
`
}

function buildEdgeDispatchSource(allowedSegments, edgeHandledPrefixes) {
  return `${banner}
/** Allowed first path segments under /api/. */
export const API_ALLOWED_SEGMENTS = new Set([
${formatArray(allowedSegments)}
])

/** Paths that should be handled by edge cache. */
export const EDGE_HANDLED_PREFIXES = new Set([
${formatArray(edgeHandledPrefixes)}
])
`
}

function readContract() {
  return JSON.parse(fs.readFileSync(contractPath, 'utf8'))
}

function main() {
  const check = process.argv.includes('--check')
  const contract = readContract()
  const api = contract.routing.edgeHandledApiPrefixes
  const extras = contract.routing.edgeHandledPathExtras
  const edgeOnly = [...api, ...extras]
  const direct = contract.frontend.directEligiblePrefixes

  const fe = buildFrontendSource(edgeOnly, direct)

  // Generate edge dispatch constants
  const backendRoutes = contract.backend.requiredRoutes || []
  // Extract first path segment from backend routes (skip /api/health, etc.)
  const allowedSegments = [...new Set(
    backendRoutes
      .filter(r => r.startsWith('/api/'))
      .map(r => r.split('/')[2])
      .filter(Boolean)
  )].sort()

  const edgeDispatch = buildEdgeDispatchSource(allowedSegments, edgeOnly)

  if (check) {
    const feDisk = fs.readFileSync(frontendOut, 'utf8')
    if (feDisk !== fe) {
      console.error(
        'Generated frontend route constants are out of date.\nRun: node scripts/generate-http-route-constants.mjs',
      )
      process.exit(1)
    }
    const edgeDisk = fs.readFileSync(edgeOut, 'utf8')
    if (edgeDisk !== edgeDispatch) {
      console.error(
        'Generated edge dispatch constants are out of date.\nRun: node scripts/generate-http-route-constants.mjs',
      )
      process.exit(1)
    }
    console.log('Generated HTTP route constants are in sync with contracts/http-routes.json')
    return
  }

  fs.writeFileSync(frontendOut, fe, 'utf8')
  console.log('Wrote:', path.relative(rootDir, frontendOut))

  fs.writeFileSync(edgeOut, edgeDispatch, 'utf8')
  console.log('Wrote:', path.relative(rootDir, edgeOut))
}

main()
